const paginate = require('./src/items');
const all = Array.from({ length: 30 }, (_, i) => i + 1);
const p1 = paginate(all, 1);
if (p1.length !== 10 || p1[0] !== 1 || p1[9] !== 10) { console.error('page 1 wrong: ' + JSON.stringify(p1)); process.exit(1); }
const p2 = paginate(all, 2);
if (p2.length !== 10 || p2[0] !== 11 || p2[9] !== 20) { console.error('page 2 wrong: ' + JSON.stringify(p2)); process.exit(1); }
console.log('ok');

